# Balanced Parentheses
def is_balanced(s):
    stack   = []
    mapping = {')':'(', '}':'{', ']':'['}
    for ch in s:
        if ch in '({[':
            stack.append(ch)
        elif ch in ')}]':
            if not stack or stack[-1] != mapping[ch]:
                return False
            stack.pop()
    return len(stack) == 0

print(is_balanced('({[]})'))   # True
print(is_balanced('({[})'))    # False
print(is_balanced('((()))'))   # True

# Infix to Postfix conversion
def infix_to_postfix(expr):
    precedence = {'+':1, '-':1, '*':2, '/':2, '**':3}
    output, stack = [], []
    for token in expr.split():
        if token.isdigit():
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()   # discard '('
        else:             # operator
            while (stack and stack[-1] != '(' and
                   precedence.get(stack[-1], 0) >= precedence.get(token, 0)):
                output.append(stack.pop())
            stack.append(token)
    while stack:
        output.append(stack.pop())
    return ' '.join(output)

print(infix_to_postfix('3 + 4 * 2'))     # 3 4 2 * +
print(infix_to_postfix('( 3 + 4 ) * 2')) # 3 4 + 2 *

# Evaluate Postfix expression
def eval_postfix(expr):
    stack = []
    for token in expr.split():
        if token.lstrip('-').isdigit():
            stack.append(int(token))
        else:
            b, a = stack.pop(), stack.pop()
            if   token == '+': stack.append(a + b)
            elif token == '-': stack.append(a - b)
            elif token == '*': stack.append(a * b)
            elif token == '/': stack.append(a // b)
    return stack[0]

print(eval_postfix('3 4 2 * +'))  # 11

import heapq

# Priority Queue using heapq (min-heap)
pq = []
heapq.heappush(pq, (3, 'low priority'))
heapq.heappush(pq, (1, 'high priority'))
heapq.heappush(pq, (2, 'medium priority'))

while pq:
    priority, task = heapq.heappop(pq)
    print(f'{priority}: {task}')
# 1: high priority
# 2: medium priority
# 3: low priority

# BFS using queue — level order traversal
from collections import deque

def bfs_levels(graph, start):
    visited = {start}
    queue   = deque([(start, 0)])   # (node, level)
    levels  = {}
    while queue:
        node, level = queue.popleft()
        levels.setdefault(level, []).append(node)
        for nb in graph[node]:
            if nb not in visited:
                visited.add(nb)
                queue.append((nb, level + 1))
    return levels

graph = {0:[1,2], 1:[3,4], 2:[5], 3:[], 4:[], 5:[]}
print(bfs_levels(graph, 0))
# {0:[0], 1:[1,2], 2:[3,4,5]}

# Queue using two stacks
class QueueUsingStacks:
    def __init__(self):
        self.in_stack  = []   # for enqueue
        self.out_stack = []   # for dequeue

    def enqueue(self, val):
        self.in_stack.append(val)

    def dequeue(self):
        if not self.out_stack:   # transfer when out is empty
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        if not self.out_stack:
            raise IndexError('Queue is empty')
        return self.out_stack.pop()

    def front(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        return self.out_stack[-1]

q = QueueUsingStacks()
q.enqueue(1); q.enqueue(2); q.enqueue(3)
print(q.dequeue())   # 1
print(q.front())     # 2

# Sliding Window Maximum — monotonic deque
from collections import deque

def sliding_window_max(nums, k):
    dq     = deque()   # stores indices, front is max
    result = []
    for i, num in enumerate(nums):
        # Remove indices outside window
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # Remove smaller elements from rear
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])  # front is max
    return result

print(sliding_window_max([1,3,-1,-3,5,3,6,7], 3))
# [3, 3, 5, 5, 6, 7]
